// The session replay plays inside the site (Joe, 2026-11-20: "without having them exit").
// The replay page itself (expert-team/, generated by the Expert Team Brain export) is not
// changed. It loads in a full-screen frame only when opened, and the frame is removed on
// close so its music and animation stop. Without JavaScript the tile is a plain link.
(() => {
    const theater = document.getElementById('replayTheater');
    const opener = document.getElementById('openReplay');
    if (!theater || !opener) return;
    const holder = theater.querySelector('.replay-frame');
    const back = theater.querySelector('.replay-back');
    let returnTo = null;
    let pushed = false;

    function track(name) {
        if (typeof gtag !== 'undefined') gtag('event', name, { event_category: 'Expert Team' });
    }

    function open(e) {
        if (e) e.preventDefault();
        returnTo = document.activeElement;
        const frame = document.createElement('iframe');
        frame.src = 'expert-team/';
        frame.title = 'The Expert Project Team, one working session replayed';
        frame.allow = 'autoplay; fullscreen';
        frame.addEventListener('load', () => {
            // Same site, so its one link back to joepointer.com can just close the replay
            // instead of loading the whole site inside the frame.
            try {
                frame.contentDocument.querySelectorAll('a[href^="https://joepointer.com"]').forEach(a =>
                    a.addEventListener('click', ev => { ev.preventDefault(); close(); }));
                frame.contentWindow.focus();
            } catch (_) { /* cross-origin in some previews: the link still works */ }
        });
        holder.replaceChildren(frame);
        theater.classList.add('on');
        document.documentElement.style.overflow = 'hidden';
        document.documentElement.classList.add('replay-open');
        back.focus();
        pushed = location.hash !== '#replay';
        if (pushed) history.pushState({ replay: 1 }, '', '#replay');
        track('replay_open');
    }

    function close(fromHistory) {
        if (!theater.classList.contains('on')) return;
        theater.classList.remove('on');
        holder.replaceChildren();
        document.documentElement.style.overflow = '';
        document.documentElement.classList.remove('replay-open');
        if (!fromHistory && pushed) history.back();
        else if (location.hash === '#replay') history.replaceState(null, '', location.pathname + location.search);
        pushed = false;
        if (returnTo && returnTo.focus) returnTo.focus();
        track('replay_close');
    }

    opener.addEventListener('click', open);
    back.addEventListener('click', () => close());
    window.addEventListener('popstate', () => close(true));
    document.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
    // A shared link to #replay opens straight into it.
    if (location.hash === '#replay') open();
})();
